import logo from './logo.svg';
import './App.css';
import LightPillar from './LightPillar';
import { Parallax, ParallaxProvider } from 'react-scroll-parallax';

function App() {
  return (
    <ParallaxProvider>
      <div className="App">

        {/* Added translateY props to define the movement range */}
        <Parallax translateY={[-20, 20]} speed={-5}>
          <div id="pillar" style={{ width: '100%', height: '100vh', position: 'absolute', zIndex: -1 }}>
            <LightPillar
              topColor="#ce466f"
              bottomColor="#ce466f"
              intensity={1}
              rotationSpeed={0.3}
              glowAmount={0.002}
              pillarWidth={3}
              pillarHeight={0.4}
              noiseIntensity={0.5}
              pillarRotation={25}
              interactive={false}
              mixBlendMode="screen"
              quality="high"
            />
          </div>
        </Parallax>

        <div id="hero">
          <div id="header-container">
            <div id="navbar">
              <svg id="logo" width="26" height="45" viewBox="0 0 26 45" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M0.3975 30L6.7015 7.6H10.5415L16.9095 30H14.1895L9.1335 11.632L8.8775 9.936C8.85617 9.808 8.7815 9.744 8.6535 9.744C8.54683 9.744 8.48283 9.808 8.4615 9.936L8.1735 11.632L3.1175 30H0.3975ZM3.8535 24.016L4.5575 21.648H12.7495L13.4535 24.016H3.8535ZM3.0535 9.936V7.6H7.5655V9.936H3.0535Z" fill="white" />
                <path d="M13.7342 33V16.2H15.7262V31.128H21.7022V33H13.7342Z" fill="white" />
              </svg>
              <div id="elements"></div>
            </div>
            <div id="title">
              Welcome to your Algorithm Learning Assistant!
            </div>
            <div id="logo-underbox">
              Completely open-source, and free!
            </div>
            <button id="get-started-button">
              Get Started!
            </button>
          </div>
        </div>

        {/* Note: Ensure this or another section has enough height to actually allow scrolling */}
        <div id="overview" style={{ height: '100vh' }}>
          {/* Content goes here */}
        </div>

      </div>
    </ParallaxProvider>
  );
}

export default App;
